/* clearMasterMdCtBuyerProfileMapping */
DELETE	ICOMCOD2
WHERE	COMPANY_CODE = 'KRKORE0001' 
AND		TEXT1 = #{ORG_CODE}
AND		TYPE = 'PFMP'
AND		FLAG = 'Y'


/* deleteMasterMdCtBuyerProfileMapping */
DELETE	ICOMCOD2
WHERE	COMPANY_CODE = 'KRKORE0001'
AND		TEXT1 = #{st_org_code}
AND		CODE = #{COM_CODE}
AND		TYPE = 'PFMP'
AND		FLAG = 'Y'
